#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;

int W;
u64 mask[20];

// Largest set bit index below b, or -1.
int pred(int b) {
    int w = b >> 6;
    u64 cur = mask[w] & ((1ULL << (b & 63)) - 1);
    while (true) {
        if (cur) return w * 64 + 63 - __builtin_clzll(cur);
        if (--w < 0) return -1;
        cur = mask[w];
    }
}

// Smallest set bit index above b, or -1.
int succ(int b) {
    int w = b >> 6;
    u64 cur = (b & 63) == 63 ? 0 : mask[w] & ~((2ULL << (b & 63)) - 1);
    while (true) {
        if (cur) return w * 64 + __builtin_ctzll(cur);
        if (++w >= W) return -1;
        cur = mask[w];
    }
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    W = n / 64 + 1;
    long long total = 0;
    for (int left = 0; left < n; left++) {
        memset(mask, 0, sizeof mask);
        long long gaps = 0;  // adjacent present values that differ by more than 1
        for (int right = left; right < n; right++) {
            int value = a[right], b = value - 1;
            if (!(mask[b >> 6] >> (b & 63) & 1)) {
                int p = pred(b), s = succ(b);
                int pv = p + 1, sv = s + 1;  // 0 means absent
                if (pv && sv && sv - pv > 1) gaps--;
                if (pv && value - pv > 1) gaps++;
                if (sv && sv - value > 1) gaps++;
                mask[b >> 6] |= 1ULL << (b & 63);
            }
            total += right == left ? 1 : gaps;
        }
    }
    cout << total % 1000000007 << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static long[] mask;

    // Largest set bit index below b, or -1.
    static int pred(int b) {
        int w = b >> 6;
        long cur = mask[w] & ((1L << (b & 63)) - 1);
        while (true) {
            if (cur != 0) return w * 64 + 63 - Long.numberOfLeadingZeros(cur);
            if (--w < 0) return -1;
            cur = mask[w];
        }
    }

    // Smallest set bit index above b, or -1.
    static int succ(int b) {
        int w = b >> 6;
        long cur = (b & 63) == 63 ? 0 : mask[w] & -(2L << (b & 63));
        while (true) {
            if (cur != 0) return w * 64 + Long.numberOfTrailingZeros(cur);
            if (++w >= mask.length) return -1;
            cur = mask[w];
        }
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        mask = new long[n / 64 + 1];
        long total = 0;
        for (int left = 0; left < n; left++) {
            Arrays.fill(mask, 0);
            long gaps = 0;
            for (int right = left; right < n; right++) {
                int value = a[right], b = value - 1;
                if ((mask[b >> 6] >>> (b & 63) & 1) == 0) {
                    int pv = pred(b) + 1, sv = succ(b) + 1;  // 0 means absent
                    if (pv != 0 && sv != 0 && sv - pv > 1) gaps--;
                    if (pv != 0 && value - pv > 1) gaps++;
                    if (sv != 0 && sv - value > 1) gaps++;
                    mask[b >> 6] |= 1L << (b & 63);
                }
                total += right == left ? 1 : gaps;
            }
        }
        System.out.println(total % 1000000007);
    }
}

package main

import (
	"fmt"
	"io"
	"math/bits"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

var mask []uint64

// pred returns the largest set bit index below b, or -1.
func pred(b int) int {
	w := b >> 6
	cur := mask[w] & (1<<(b&63) - 1)
	for {
		if cur != 0 {
			return w*64 + 63 - bits.LeadingZeros64(cur)
		}
		if w--; w < 0 {
			return -1
		}
		cur = mask[w]
	}
}

// succ returns the smallest set bit index above b, or -1.
func succ(b int) int {
	w := b >> 6
	cur := uint64(0)
	if b&63 != 63 {
		cur = mask[w] &^ (2<<(b&63) - 1)
	}
	for {
		if cur != 0 {
			return w*64 + bits.TrailingZeros64(cur)
		}
		if w++; w >= len(mask) {
			return -1
		}
		cur = mask[w]
	}
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	mask = make([]uint64, n/64+1)
	total := 0
	for left := 0; left < n; left++ {
		clear(mask)
		gaps := 0
		for right := left; right < n; right++ {
			value := a[right]
			b := value - 1
			if mask[b>>6]>>(b&63)&1 == 0 {
				pv, sv := pred(b)+1, succ(b)+1 // 0 means absent
				if pv != 0 && sv != 0 && sv-pv > 1 {
					gaps--
				}
				if pv != 0 && value-pv > 1 {
					gaps++
				}
				if sv != 0 && sv-value > 1 {
					gaps++
				}
				mask[b>>6] |= 1 << (b & 63)
			}
			if right == left {
				total++
			} else {
				total += gaps
			}
		}
	}
	fmt.Println(total % 1000000007)
}
